function validate([root]) {
  if (!Array.isArray(root)) return 'root must be a level-order list.';
  if (root.length > 50000) return 'The tree has at most 5 * 10^4 nodes.';
  if (root.some(v => v === null)) return 'The tree must be complete: level order has no gaps.';
  if (root.some(v => !Number.isInteger(v) || v < 0 || v > 50000)) return 'Each node value is a whole number from 0 to 5 * 10^4.';
  return null;
}

