function countNodes(root) {
  if (!root) return 0;

  let leftHeight = 0;
  let node = root;
  while (node) {
    leftHeight++;
    node = node.left;
  }
  let rightHeight = 0;
  node = root;
  while (node) {
    rightHeight++;
    node = node.right;
  }

  if (leftHeight === rightHeight) {
    return 2 ** leftHeight - 1;
  }
  return 1 + countNodes(root.left) + countNodes(root.right);
}

